inline Image pattern(int w,int h){Image im(w,h);for(int y=0;y<h;y++)for(int x=0;x<w;x++){float a=((x/32+y/32)%5==0)?0.f:float(64+(x*3+y*7)%192)/255.f;im.p[std::size_t(y)*w+x]={a*float(x%256)/255.f,a*float(y%256)/255.f,a*float((x+y)%256)/255.f,a};}return im;}
inline Json selftest(bool gpuRequired){
 int checks=0;auto check=[&](bool b,const char*m){++checks;need(b,m);};auto rejects=[&](auto f){bool failed=false;try{f();}catch(const std::exception&){failed=true;}check(failed,"negative control did not reject");};
 Image fixed(91,57);for(auto&p:fixed.p)p={.12f,.3f,.2f,.5f};for(auto f:{Filter::Lanczos3,Filter::Mitchell,Filter::Area})for(auto q:std::vector<std::array<int,2>>{{1,1},{13,31},{40,7},{91,57}}){auto r=resize_cpu(fixed,q[0],q[1],f);for(auto p:r.p)check(std::abs(p.g-.3f)<1e-5f&&std::abs(p.a-.5f)<1e-5f,"DC gain/alpha invariant");}
 Image cb(64,64);for(size_t i=0;i<cb.p.size();i++){float x=float((i+i/64)%2);cb.p[i]={x,x,x,1};}auto rgba=quantize(resize_cpu(cb,1,1,Filter::Area),true);check(rgba[0]==188&&rgba[3]==255,"linear light should average black/white to sRGB 188");
 Image transparent(91,57);auto q=quantize(resize_cpu(transparent,11,7,Filter::Lanczos3),true);for(auto b:q)check(b==0,"transparent output is not zero");
 rejects([&]{resize_cpu(cb,65,64,Filter::Area);});rejects([&]{crop_image(cb,{-1,0,10,10});});rejects([&]{parse_json(std::vector<BYTE>{'{','"','x','"',':','1',',','"','x','"',':','2','}'});});rejects([&]{clean_path(path("C:/tmp/../evil"));});rejects([&]{clean_path(path("C:/tmp/image.png:payload"));});
 Wic w;auto im=pattern(91,57);auto p=quantize(im,false);for(bool adaptive:{false,true}){auto bytes=w.encode(p,91,57,adaptive);check(w.decode_rgba(bytes,91,57)==p,"WIC lossless RGBA roundtrip");std::string note;auto decoded=w.decode(bytes,true,note);check(decoded.w==91&&decoded.h==57,"decode dimensions");check(quantize(decoded,true)==p,"16-bit WIC path and sRGB roundtrip");}
 Gpu gpu;Json gtest={{"hardware",gpu.info}};if(gpuRequired)check(gpu.available,"required hardware GPU missing");if(gpu.available){float maximum=0;int max8=0;
  for(auto f:{Filter::Lanczos3,Filter::Mitchell,Filter::Area})for(auto dims:std::vector<std::array<int,2>>{{97,67},{769,513},{23,71}}){auto in=pattern(dims[0],dims[1]);std::vector<std::array<int,2>>sizes={{1,1},{7,11},{13,17}};std::lock_guard lock(gpu.mutex);auto gr=gpu.resize_many_locked(in,sizes,f);
   for(size_t i=0;i<sizes.size();i++){auto cr=resize_cpu(in,sizes[i][0],sizes[i][1],f);auto a=quantize(cr,true),b=quantize(gr[i],true);for(size_t k=0;k<a.size();k++)max8=std::max(max8,std::abs(int(a[k])-b[k]));for(size_t k=0;k<cr.p.size();k++)for(int c=0;c<4;c++)maximum=std::max(maximum,std::abs((&cr.p[k].r)[c]-(&gr[i].p[k].r)[c]));}
  }check(maximum<5e-5f,"GPU/CPU float mismatch");check(max8<=1,"GPU/CPU 8-bit pixel difference above one LSB");gtest.update({{"tested",true},{"max_float_error",maximum},{"max_channel_8bit_difference",max8}});
 }else gtest["tested"]=false;
 return{{"schema","h3.tier-export.selftest.v1"},{"passed",true},{"checks",checks},{"gpu",gtest},{"files_written",0},{"image_generation_calls",0}};
}
