 bool linear=settings["space"]=="linear";Filter filter=parse_filter(settings["filter"]);std::unique_ptr<Gpu>gpu;bool autoGpu=false;if(settings["backend"]!="cpu"){gpu=std::make_unique<Gpu>(settings["adapter"],settings["gpu_memory_mib"]);need(settings["backend"]!="gpu"||gpu->available,"GPU benchmark unavailable");if(gpu->available){auto calibration=auto_calibrate(*gpu);autoGpu=calibration["gpu_selected"];}}
 unsigned threads=std::min<unsigned>(settings["workers"].get<unsigned>(),unsigned(jobCount));auto host=host_memory();std::uint64_t available=host["available_bytes"],budget=settings["memory_gib"].get<std::uint64_t>()*1024*1024*1024;MemoryGate memory(std::min(budget,available*3/4));std::atomic<int>next=0;std::mutex mx;Json result=Json::array();auto start=Clock::now();std::vector<std::thread>workers;
 for(unsigned n=0;n<threads;n++)workers.emplace_back([&]{ComInit com;Wic w;while(true){int i=next++;if(i>=jobCount)break;bool large=i%3==2;auto begin=Clock::now();Json r={{"job",i},{"large",large}};try{MemoryLease lease(memory,large?1024ull*1024*1024:512ull*1024*1024);auto t=Clock::now();auto bytes=read_all(out/(large?L"large-fixture.png":L"icon-fixture.png"));std::string note;auto im=w.decode(bytes,linear,note);r["read_decode_ms"]=ms(t);std::vector<std::array<int,2>>sizes=large?std::vector<std::array<int,2>>{{800,450},{1600,900},{2400,1350}}:std::vector<std::array<int,2>>{{44,44},{88,88},{132,132}};std::vector<Image>images;std::string backend="cpu",mode=settings["backend"];t=Clock::now();
  if(gpu&&gpu->available&&(mode!="auto"||autoGpu)){std::unique_lock<std::mutex>lock(gpu->mutex,std::defer_lock);if(mode=="gpu"?(lock.lock(),true):lock.try_lock()){try{images=gpu->resize_many_locked(im,sizes,filter);backend="gpu";}catch(const std::exception&e){r["gpu_fallback"]=e.what();if(mode=="gpu")throw;}}}if(images.empty())for(auto s:sizes)images.push_back(resize_cpu(im,s[0],s[1],filter));r["resize_transfer_ms"]=ms(t);r["backend"]=backend;t=Clock::now();std::uint64_t written=0;Json hashes=Json::array();for(size_t k=0;k<images.size();k++){auto pixels=quantize(images[k],linear);auto png=w.encode(pixels,images[k].w,images[k].h,settings["png_filter"]=="adaptive");auto p=out/path("job-"+std::to_string(i)+"-"+std::to_string(k+1)+"x.png");write_new(p,png);auto readback=read_all(p);need(readback==png&&w.decode_rgba(readback,images[k].w,images[k].h)==pixels,"benchmark roundtrip failure");hashes.push_back(sha(pixels));written+=png.size();}r["encode_write_verify_ms"]=ms(t);r["output_bytes"]=written;r["pixel_hashes"]=hashes;r["status"]="OK";}catch(const std::exception&e){r["status"]="FAILED";r["error"]=e.what();}r["total_ms"]=ms(begin);std::lock_guard lock(mx);result.push_back(r);}});
 for(auto&t:workers)t.join();double wall=ms(start);size_t failed=0,gpus=0;std::vector<double>times;for(auto&r:result){failed+=r["status"]!="OK";gpus+=r.value("backend","")=="gpu";times.push_back(r["total_ms"]);}std::sort(times.begin(),times.end());auto percentile=[&](double x){return times[std::min(times.size()-1,size_t(std::ceil(x*times.size())-1))];};Json report={{"schema","h3.tier-export.benchmark.v1"},{"created_utc",now()},{"fixture_only",true},{"native_generated_master",false},{"host",host},{"settings",settings},{"gpu",gpu?gpu->info:Json(nullptr)},{"jobs",jobCount},{"gpu_jobs",gpus},{"cpu_jobs",jobCount-failed-gpus},{"failed",failed},{"workers",threads},{"wall_ms",wall},{"masters_per_second",(jobCount-failed)/(wall/1000.)},{"latency_p50_ms",percentile(.5)},{"latency_p95_ms",percentile(.95)},{"peak_working_set_bytes",peak_rss()},{"peak_admitted_estimate_bytes",memory.peak},{"includes",{"disk reads (OS cache not cleared)","WIC decode/color transform","three independent reductions","GPU upload/readback when selected","PNG encoding","flush and readback byte/pixel validation"}},{"excludes",{"fixture preparation","GPU shader creation and startup parity/calibration","real artwork visual acceptance"}},{"results",result}};write_json_new(out/L"benchmark.json",report);return report;
